"""Pluggable embedding backends for the metadata-aware RAG system.

Two backends are provided:

* :class:`HashingEmbedder` -- a pure-NumPy, deterministic hashed bag-of-words
  embedder with sublinear term-frequency weighting and L2 normalization. It
  requires no model downloads, no API keys, and runs anywhere NumPy runs.
* :class:`SentenceTransformerEmbedder` -- higher-quality transformer
  embeddings via the optional ``sentence-transformers`` package.
"""
from __future__ import annotations

import hashlib
import math
import re
from abc import ABC, abstractmethod
from typing import Any, Dict, List

import numpy as np


def tokenize(text: str) -> List[str]:
    """Lowercase alphanumeric tokenization (shared by sparse/dense backends)."""
    return re.findall(r"[a-z0-9]+", text.lower())


class Embedder(ABC):
    """Interface for text -> vector models.

    Implementations must return unit-length rows so cosine similarity is a
    simple dot product.
    """

    dim: int

    @abstractmethod
    def embed(self, texts: List[str]) -> np.ndarray:
        """Return an (n, dim) float32 matrix of L2-normalized vectors."""

    def embed_one(self, text: str) -> np.ndarray:
        return self.embed([text])[0]


class HashingEmbedder(Embedder):
    """Deterministic hashed bag-of-words embedder (no external dependencies).

    Each token is hashed (MD5) into a fixed-dimension feature space. Weights
    use sublinear term frequency (1 + log(count)), and rows are L2 normalized.
    """

    def __init__(self, dim: int = 1024):
        self.dim = dim

    def _vectorize(self, text: str) -> np.ndarray:
        vec = np.zeros(self.dim, dtype=np.float64)
        counts: Dict[str, int] = {}
        for token in tokenize(text):
            counts[token] = counts.get(token, 0) + 1
        for token, count in counts.items():
            idx = int(hashlib.md5(token.encode("utf-8")).hexdigest(), 16) % self.dim
            vec[idx] += 1.0 + math.log(count)
        return vec

    def embed(self, texts: List[str]) -> np.ndarray:
        if not texts:
            return np.zeros((0, self.dim), dtype=np.float32)
        matrix = np.stack([self._vectorize(t) for t in texts])
        norms = np.linalg.norm(matrix, axis=1, keepdims=True)
        norms[norms == 0] = 1.0
        return (matrix / norms).astype(np.float32)


class SentenceTransformerEmbedder(Embedder):
    """Higher-quality embeddings via ``sentence-transformers`` (optional)."""

    def __init__(self, model_name: str = "all-MiniLM-L6-v2"):
        try:
            from sentence_transformers import SentenceTransformer
        except ImportError as exc:  # pragma: no cover
            raise ImportError(
                "sentence-transformers is not installed. Run: pip install sentence-transformers"
            ) from exc
        self.model_name = model_name
        self._model = SentenceTransformer(model_name)
        self.dim = int(self._model.get_sentence_embedding_dimension())

    def embed(self, texts: List[str]) -> np.ndarray:
        if not texts:
            return np.zeros((0, self.dim), dtype=np.float32)
        return self._model.encode(
            texts, normalize_embeddings=True, convert_to_numpy=True
        ).astype(np.float32)


def embedder_config(embedder: Embedder) -> Dict[str, Any]:
    """Serialize an embedder so it can be recreated when an index is loaded."""
    if isinstance(embedder, HashingEmbedder):
        return {"type": "HashingEmbedder", "dim": embedder.dim}
    if isinstance(embedder, SentenceTransformerEmbedder):
        return {"type": "SentenceTransformerEmbedder", "model_name": embedder.model_name}
    raise ValueError(f"Unsupported embedder for persistence: {type(embedder).__name__}")


def build_embedder(config: Dict[str, Any]) -> Embedder:
    """Recreate an embedder from a configuration dict (see embedder_config)."""
    kind = config.get("type")
    if kind == "HashingEmbedder":
        return HashingEmbedder(dim=int(config.get("dim", 1024)))
    if kind == "SentenceTransformerEmbedder":
        return SentenceTransformerEmbedder(
            model_name=config.get("model_name", "all-MiniLM-L6-v2")
        )
    raise ValueError(f"Unknown embedder type: {kind!r}")

"""In-memory vector index with metadata; NumPy cosine similarity.

Stores chunks alongside their embeddings and supports optional persistence to
disk so an index can be built once and queried later (see the CLI).
"""
from __future__ import annotations

import pickle
from dataclasses import dataclass
from pathlib import Path
from typing import List, Optional, Sequence, Union

import numpy as np

from .chunker import Chunk
from .embeddings import Embedder, build_embedder, embedder_config


@dataclass
class ScoredChunk:
    """A retrieval result: the chunk, its (possibly boosted) score, and rank."""

    chunk: Chunk
    score: float
    rank: int
    index: int = -1


class VectorStore:
    """Stores chunks and their embeddings; supports search and persistence."""

    def __init__(self, embedder: Embedder):
        self.embedder = embedder
        self._chunks: List[Chunk] = []
        self._matrix: Optional[np.ndarray] = None

    @property
    def chunks(self) -> List[Chunk]:
        return self._chunks

    @property
    def matrix(self) -> Optional[np.ndarray]:
        return self._matrix

    @property
    def size(self) -> int:
        return len(self._chunks)

    def add(self, chunks: Sequence[Chunk]) -> None:
        """Add chunks, embedding them with the configured embedder."""
        if not chunks:
            return
        self._chunks.extend(chunks)
        new_matrix = self.embedder.embed([c.content for c in chunks])
        self._matrix = (
            new_matrix
            if self._matrix is None
            else np.vstack([self._matrix, new_matrix])
        )

    def similarity_search(self, query: str, k: int = 5) -> List[ScoredChunk]:
        """Dense retrieval: cosine similarity (dot product on unit vectors)."""
        if self._matrix is None or self._matrix.shape[0] == 0:
            return []
        query_vec = self.embedder.embed_one(query)
        sims = self._matrix @ query_vec
        order = np.argsort(sims)[::-1][:k]
        return [
            ScoredChunk(
                chunk=self._chunks[int(i)],
                score=float(sims[int(i)]),
                rank=r,
                index=int(i),
            )
            for r, i in enumerate(order)
        ]

    def save(self, path: Union[str, Path]) -> None:
        payload = {
            "chunks": self._chunks,
            "matrix": self._matrix,
            "embedder": embedder_config(self.embedder),
        }
        with open(path, "wb") as fh:
            pickle.dump(payload, fh)

    @staticmethod
    def load(path: Union[str, Path]) -> "VectorStore":
        with open(path, "rb") as fh:
            payload = pickle.load(fh)
        store = VectorStore(build_embedder(payload["embedder"]))
        store._chunks = payload["chunks"]
        store._matrix = payload["matrix"]
        return store

"""Declarative metadata filtering and metadata-aware ranking.

Two complementary pieces:

1. :class:`MetadataFilter` -- hard constraints applied *before* ranking
   (e.g. only ``category == "official"``, ``date >= "2024-01-01"``,
   ``tags contains "install"``).

2. :class:`MetadataRanker` -- soft *relevance multipliers* applied *after*
   semantic scoring. Field/value boost rules amplify documents whose metadata
   the user deems important (e.g. official docs, a preferred source, a
   priority tag). An optional recency rule applies exponential time decay so
   newer documents rank higher.
"""
from __future__ import annotations

import math
import operator
import re
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Any, Dict, Iterable, List, Optional, Sequence, Union

_COMPARATORS = {
    "eq": operator.eq,
    "ne": operator.ne,
    "gt": operator.gt,
    "gte": operator.ge,
    "lt": operator.lt,
    "lte": operator.le,
}

_SPECIAL_OPS = ("in", "contains", "icontains", "matches", "exists")


def _coerce(value: Any) -> Any:
    """Coerce numeric-looking strings so ordering comparisons behave numerically."""
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            return value
    return value


def _parse_date(value: Any) -> Optional[date]:
    """Parse ISO-8601 date/datetime strings or datetime/date objects."""
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    if isinstance(value, str):
        text = value.strip()
        try:
            return date.fromisoformat(text[:10])
        except ValueError:
            try:
                return datetime.fromisoformat(text).date()
            except ValueError:
                return None
    return None


@dataclass
class FilterRule:
    """A single metadata predicate: ``<field> <op> <value>``."""

    field: str
    op: str = "eq"
    value: Any = None

    def apply(self, metadata: Dict[str, Any]) -> bool:
        if self.op == "exists":
            return metadata.get(self.field) is not None
        if self.field not in metadata:
            return False
        actual = metadata[self.field]
        if self.op == "in":
            return actual in self.value
        if self.op == "contains":
            return isinstance(actual, str) and self.value in actual
        if self.op == "icontains":
            return isinstance(actual, str) and str(self.value).lower() in actual.lower()
        if self.op == "matches":
            return isinstance(actual, str) and re.search(str(self.value), actual) is not None
        fn = _COMPARATORS.get(self.op)
        if fn is None:
            raise ValueError(f"Unknown filter operator: {self.op!r}")
        return fn(_coerce(actual), _coerce(self.value))


@dataclass
class MetadataFilter:
    """AND-combined filter rules applied to chunk metadata before ranking."""

    rules: List[FilterRule] = field(default_factory=list)

    @classmethod
    def from_spec(cls, spec: Any) -> "MetadataFilter":
        """Build a filter from None, a rule list, or a shorthand dict.

        Shorthand dict forms::

            {"category": "official"}                      # eq
            {"tags": {"in": ["install", "linux"]}}        # operator key form
            {"date": {"gte": "2024-01-01"}}
            [{"field": "category", "op": "eq", "value": "official"}]
        """
        if spec is None:
            return cls()
        if isinstance(spec, MetadataFilter):
            return spec
        if isinstance(spec, dict):
            return cls(rules=[cls._parse_rule(k, v) for k, v in spec.items()])
        if isinstance(spec, (list, tuple)):
            return cls(rules=[cls._parse_rule(r) for r in spec])
        raise TypeError(f"Cannot build MetadataFilter from {type(spec).__name__}")

    @staticmethod
    def _parse_rule(field: Any, value: Any = None) -> FilterRule:
        if isinstance(field, FilterRule):
            return field
        if isinstance(field, dict):
            return FilterRule(
                field=field["field"],
                op=field.get("op", "eq"),
                value=field.get("value"),
            )
        if isinstance(value, dict):
            if "op" in value:
                return FilterRule(field=field, op=value["op"], value=value.get("value"))
            for op in _SPECIAL_OPS + ("eq", "ne", "gt", "gte", "lt", "lte"):
                if op in value:
                    return FilterRule(field=field, op=op, value=value[op])
            return FilterRule(field=field, value=value)
        return FilterRule(field=field, value=value)

    def matches(self, metadata: Dict[str, Any]) -> bool:
        return all(rule.apply(metadata) for rule in self.rules)

    def __call__(self, items: Iterable[Any]) -> List[Any]:
        """Filter chunks or ScoredChunk objects."""
        result = []
        for item in items:
            metadata = item.chunk.metadata if hasattr(item, "chunk") else item.metadata
            if self.matches(metadata):
                result.append(item)
        return result


@dataclass
class BoostRule:
    """Field/value -> relevance multiplier for metadata-aware ranking."""

    field: str
    values: Dict[Any, float]
    default: float = 1.0

    def multiplier(self, metadata: Dict[str, Any]) -> float:
        return float(self.values.get(metadata.get(self.field), self.default))


@dataclass
class RecencyRule:
    """Exponential time-decay multiplier for a date metadata field.

    ``multiplier = exp(-age_days / half_life_days)``, so documents older than
    one half-life score roughly half as well on this factor.
    """

    field: str
    half_life_days: float = 180.0
    ref_date: Optional[Union[str, date, datetime]] = None

    def multiplier(self, metadata: Dict[str, Any]) -> float:
        doc_date = _parse_date(metadata.get(self.field))
        if doc_date is None:
            return 1.0
        ref = _parse_date(self.ref_date) or date.today()
        age_days = max((ref - doc_date).days, 0)
        return math.exp(-age_days / self.half_life_days)


class MetadataRanker:
    """Boosts semantic scores with metadata multipliers.

    final_score = semantic_score * (1 + mix * (metadata_multiplier - 1))

    * ``mix = 0.0`` -> pure semantic ranking.
    * ``mix = 1.0`` (default) -> full metadata boost.
    """

    def __init__(
        self,
        boost_rules: Optional[Sequence[Union[BoostRule, Dict[str, Any]]]] = None,
        recency: Optional[Union[RecencyRule, Dict[str, Any]]] = None,
        mix: float = 1.0,
    ):
        self.boost_rules: List[BoostRule] = [
            r if isinstance(r, BoostRule) else BoostRule(**r)
            for r in (boost_rules or [])
        ]
        self.recency = (
            recency
            if isinstance(recency, RecencyRule)
            else (RecencyRule(**recency) if recency else None)
        )
        self.mix = mix

    def multiplier(self, metadata: Dict[str, Any]) -> float:
        value = 1.0
        for rule in self.boost_rules:
            value *= rule.multiplier(metadata)
        if self.recency is not None:
            value *= self.recency.multiplier(metadata)
        return value

    def rerank(self, scored: Sequence[Any]) -> List[Any]:
        result = list(scored)
        for item in result:
            metadata = item.chunk.metadata if hasattr(item, "chunk") else item.metadata
            mult = self.multiplier(metadata)
            item.score = item.score * (1.0 + self.mix * (mult - 1.0))
        result.sort(key=lambda s: s.score, reverse=True)
        return result

    def __call__(self, scored: Sequence[Any]) -> List[Any]:
        return self.rerank(scored)

"""End-to-end RAG pipeline: retrieve (filter + rank) then generate.

Wires a :class:`~rag_metadata.retriever.Retriever` (which already applies
metadata filters and the metadata ranker) to a generator. Returns the answer
together with ranked sources so responses can be audited and cited.
"""
from __future__ import annotations

from typing import Any, Dict, List, Optional

from .llm import ExtractiveAnswerer
from .retriever import Retriever

DEFAULT_PROMPT = (
    'You are a helpful assistant. Answer the question using ONLY the provided '
    'context. If the context does not contain the answer, say "I don\'t have '
    'enough information."\n\nContext:\n{context}\n\nQuestion: {question}\n\nAnswer:'
)


class RAGPipeline:
    """Wires a metadata-aware retriever to a generator."""

    def __init__(
        self,
        retriever: Retriever,
        generator: Any = None,
        prompt_template: str = DEFAULT_PROMPT,
    ):
        self.retriever = retriever
        self.prompt_template = prompt_template
        embedder = getattr(getattr(retriever, "vectorstore", None), "embedder", None)
        self.generator = (
            generator if generator is not None else ExtractiveAnswerer(embedder=embedder)
        )

    def retrieve(self, query: str, **kwargs) -> List[Any]:
        return self.retriever.retrieve(query, **kwargs)

    def build_context(self, scored: List[Any]) -> str:
        parts = []
        for i, item in enumerate(scored, start=1):
            meta = item.chunk.metadata
            label = f"[{i}] (source={meta.get('source', '?')}"
            if meta.get("category"):
                label += f", category={meta['category']}"
            label += ")"
            parts.append(f"{label} {item.chunk.content}")
        return "\n\n".join(parts)

    def answer(
        self,
        query: str,
        k: Optional[int] = None,
        metadata_filter: Any = None,
        ranker: Any = None,
        return_sources: bool = True,
    ) -> Dict[str, Any]:
        scored = self.retriever.retrieve(
            query, k=k, metadata_filter=metadata_filter, ranker=ranker
        )
        context = self.build_context(scored)
        answer = self.generator(context, query)
        result: Dict[str, Any] = {"query": query, "answer": answer}
        if return_sources:
            result["sources"] = [
                {
                    "rank": i,
                    "score": round(float(item.score), 4),
                    "id": item.chunk.id,
                    "metadata": dict(item.chunk.metadata),
                    "content": item.chunk.content,
                }
                for i, item in enumerate(scored, start=1)
            ]
        return result

