        if self.op == "in":
            return actual in self.value
        if self.op == "contains":
            return isinstance(actual, str) and self.value in actual
        if self.op == "icontains":
            return isinstance(actual, str) and str(self.value).lower() in actual.lower()
        if self.op == "matches":
            return isinstance(actual, str) and re.search(str(self.value), actual) is not None
        fn = _COMPARATORS.get(self.op)
        if fn is None:
            raise ValueError(f"Unknown filter operator: {self.op!r}")
        return fn(_coerce(actual), _coerce(self.value))


@dataclass
class MetadataFilter:
    """AND-combined filter rules applied to chunk metadata before ranking."""

    rules: List[FilterRule] = field(default_factory=list)

    @classmethod
    def from_spec(cls, spec: Any) -> "MetadataFilter":
        """Build a filter from None, a rule list, or a shorthand dict.

        Shorthand dict forms::

            {"category": "official"}                      # eq
            {"tags": {"in": ["install", "linux"]}}        # operator key form
            {"date": {"gte": "2024-01-01"}}
            [{"field": "category", "op": "eq", "value": "official"}]
        """
        if spec is None:
            return cls()
        if isinstance(spec, MetadataFilter):
            return spec
        if isinstance(spec, dict):
            return cls(rules=[cls._parse_rule(k, v) for k, v in spec.items()])
        if isinstance(spec, (list, tuple)):
            return cls(rules=[cls._parse_rule(r) for r in spec])
        raise TypeError(f"Cannot build MetadataFilter from {type(spec).__name__}")

    @staticmethod
    def _parse_rule(field: Any, value: Any = None) -> FilterRule:
        if isinstance(field, FilterRule):
            return field
        if isinstance(field, dict):
            return FilterRule(
                field=field["field"],
                op=field.get("op", "eq"),
                value=field.get("value"),
            )
        if isinstance(value, dict):
            if "op" in value:
                return FilterRule(field=field, op=value["op"], value=value.get("value"))
            for op in _SPECIAL_OPS + ("eq", "ne", "gt", "gte", "lt", "lte"):
                if op in value:
                    return FilterRule(field=field, op=op, value=value[op])
            return FilterRule(field=field, value=value)
        return FilterRule(field=field, value=value)

    def matches(self, metadata: Dict[str, Any]) -> bool:
        return all(rule.apply(metadata) for rule in self.rules)

    def __call__(self, items: Iterable[Any]) -> List[Any]:
        """Filter chunks or ScoredChunk objects."""
        result = []
        for item in items:
            metadata = item.chunk.metadata if hasattr(item, "chunk") else item.metadata
            if self.matches(metadata):
                result.append(item)
        return result

